#!/usr/bin/env node
// Generated by mcp-forge. Tool definitions live in tools.json; edit
// forge.config.yaml and regenerate rather than editing generated files.
import { readFileSync } from "node:fs";
import { McpServer, fromJsonSchema } from "@modelcontextprotocol/server";
import { serveStdio } from "@modelcontextprotocol/server/stdio";
import { createHttpRuntime } from "./lib/http-runtime.mjs";
import { createCliRuntime } from "./lib/cli-runtime.mjs";
import { createElectronRuntime } from "./lib/electron-runtime.mjs";
import { createAdbRuntime } from "./lib/adb-runtime.mjs";

const manifest = JSON.parse(readFileSync(new URL("./tools.json", import.meta.url), "utf8"));
const runtimes = {};
const factories = { adb: createAdbRuntime, cli: createCliRuntime, electron: createElectronRuntime, http: createHttpRuntime };
const runtimeFor = (kind) => (runtimes[kind] ??= factories[kind](manifest, process.env));
// A launched app must not outlive the server: stop it when the client disconnects.
const shutdown = () => runtimes.electron?.close();
process.on("exit", shutdown);
process.stdin.on("end", shutdown);
for (const signal of ["SIGINT", "SIGTERM"]) process.on(signal, () => (shutdown(), process.exit(0)));

const fail = (text) => ({ isError: true, content: [{ type: "text", text }] });

/** Delete fields at dotted paths (`items[].session_id`); the server keeps session secrets to itself. */
function omitFields(value, paths) {
  const drop = (node, parts) => {
    if (node == null || typeof node !== "object" || parts.length === 0) return;
    const [head, ...rest] = parts;
    const isArray = head.endsWith("[]");
    const key = isArray ? head.slice(0, -2) : head;
    if (rest.length === 0 && !isArray) {
      delete node[key];
      return;
    }
    const child = key === "" ? node : node[key];
    if (isArray) for (const item of Array.isArray(child) ? child : []) drop(item, rest);
    else drop(child, rest);
  };
  for (const path of paths) drop(value, path.split("."));
  return value;
}

function parseJsonText(text) {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

function cliResult(action, run) {
  if (run.exit_code !== 0) {
    const detail = (run.stderr || run.stdout).trim().slice(0, 2000);
    return fail(`${action.binding.subcommand.join(" ") || "command"} exited ${run.exit_code}${run.signal ? ` (${run.signal})` : ""}: ${detail}`);
  }
  if (action.binding.output === "json") {
    const json = parseJsonText(run.stdout.trim());
    if (json === undefined) return fail(`Expected JSON output but got: ${run.stdout.slice(0, 500)}`);
    if (!action.output && (json === null || typeof json !== "object" || Array.isArray(json))) return { content: [{ type: "text", text: run.stdout }] };
    const structured = omitFields(action.output_wrapped_as ? { [action.output_wrapped_as]: json } : json, action.omit_fields ?? []);
    return { content: [{ type: "text", text: JSON.stringify(structured) }], structuredContent: structured };
  }
  const structured = { stdout: run.stdout.replace(/\s+$/, "") };
  return { content: [{ type: "text", text: structured.stdout || "(no output)" }], structuredContent: structured };
}

function callResult(action, call) {
  if (!call.ok) return fail(`${action.binding.kind === "adb" ? action.binding.op : `${action.binding.api}.${action.binding.member}`} failed: ${call.error}`);
  if (call.value === undefined) return { content: [{ type: "text", text: action.binding.ipc_mode === "send" ? "Sent." : "Done (no return value)." }] };
  if (!action.output && (call.value === null || typeof call.value !== "object" || Array.isArray(call.value))) {
    return { content: [{ type: "text", text: JSON.stringify(call.value) }] };
  }
  const structured = omitFields(action.output_wrapped_as ? { [action.output_wrapped_as]: call.value } : call.value, action.omit_fields ?? []);
  return { content: [{ type: "text", text: JSON.stringify(structured) }], structuredContent: structured };
}

function toolResult(action, response) {
  if (action.binding.kind === "cli") return cliResult(action, response);
  // Electron and adb runtimes both answer { ok, value | error }.
  if (action.binding.kind === "electron" || action.binding.kind === "adb") return callResult(action, response);
  if (response.status < 200 || response.status >= 300) {
    return fail(`HTTP ${response.status} from ${action.binding.method} ${action.binding.path_template}: ${response.text.slice(0, 2000)}`);
  }
  if (!action.output) {
    return { content: [{ type: "text", text: response.text || `HTTP ${response.status}` }] };
  }
  const structured = omitFields(action.output_wrapped_as ? { [action.output_wrapped_as]: response.json } : response.json, action.omit_fields ?? []);
  return { content: [{ type: "text", text: JSON.stringify(structured) }], structuredContent: structured };
}

/** Pick the operation a call targets and translate tool arguments to its arguments. */
function route(tool, args) {
  const action = tool.actions.length === 1 && tool.actions[0].action === null ? tool.actions[0] : tool.actions.find((a) => a.action === args.action);
  if (!action) return { error: `Unknown action ${JSON.stringify(args.action)}; expected one of ${tool.actions.map((a) => a.action).join(", ")}.` };
  const missing = action.required.filter((name) => args[name] === undefined);
  if (missing.length) return { error: `Action ${action.action ?? tool.name} requires: ${missing.join(", ")}.` };
  const opArgs = {};
  for (const [name, value] of Object.entries(args)) {
    if (name === "action" && action.action !== null) continue;
    opArgs[action.arg_map[name] ?? name] = value;
  }
  return { action, opArgs };
}

// ---- pinned arguments and guards ---------------------------------------------
// Pinned arguments are filled in here, never by the agent; guards are checked
// before the call. Both may call read-only "support" operations from tools.json.

function pointerGet(value, pointer) {
  if (!pointer || pointer === "/") return value;
  return pointer
    .split("/")
    .slice(1)
    .map((p) => p.replace(/~1/g, "/").replace(/~0/g, "~"))
    .reduce((v, key) => (v == null ? undefined : v[key]), value);
}

/** Fill {name} placeholders; a template that is exactly one placeholder keeps the value's type. */
function fillTemplate(template, vars) {
  if (typeof template !== "string") return template;
  const whole = /^\{([\w.]+)\}$/.exec(template);
  const lookup = (name) => {
    if (!(name in vars) || vars[name] === undefined) throw new Error(`Cannot fill {${name}}: no such argument or pinned value.`);
    return vars[name];
  };
  if (whole) return lookup(whole[1]);
  return template.replace(/\{([\w.]+)\}/g, (_, name) => String(lookup(name)));
}

/** The JSON value of a successful support call, whatever the runtime. */
function responseValue(action, res) {
  const where = action.operation_id;
  switch (action.binding.kind) {
    case "http":
      if (res.status < 200 || res.status >= 300) throw new Error(`${where} answered HTTP ${res.status}: ${res.text.slice(0, 300)}`);
      return res.json;
    case "cli":
      if (res.exit_code !== 0) throw new Error(`${where} exited ${res.exit_code}: ${(res.stderr || res.stdout).slice(0, 300)}`);
      return action.binding.output === "json" ? JSON.parse(res.stdout) : { stdout: res.stdout };
    default:
      if (!res.ok) throw new Error(`${where} failed: ${res.error}`);
      return res.value;
  }
}

const supportCache = new Map();
async function callSupport(id, args, cache) {
  const op = manifest.support?.[id];
  if (!op) throw new Error(`Support operation ${id} is missing from tools.json; regenerate the server.`);
  const key = `${id} ${JSON.stringify(args)}`;
  if (cache && supportCache.has(key)) return supportCache.get(key);
  const value = responseValue(op, await runtimeFor(op.binding.kind).invoke(op, args));
  if (cache) supportCache.set(key, value);
  return value;
}

/** Arguments with pins applied (fixed, derived, then templates), plus computed-only values. */
async function applyPins(action, opArgs) {
  const pins = Object.entries(action.pins ?? {});
  if (!pins.length) return { sendArgs: opArgs, vars: opArgs };
  const vars = { ...opArgs };
  for (const [name, pin] of pins) {
    if ("value" in pin) vars[name] = pin.value;
    else if ("from" in pin) {
      const value = pointerGet(await callSupport(pin.from, pin.args ?? {}, true), pin.pointer);
      if (value === undefined || value === null) throw new Error(`Could not work out ${name}: ${pin.from} returned nothing at ${pin.pointer}.`);
      vars[name] = value;
    }
  }
  for (const [name, pin] of pins) if ("template" in pin) vars[name] = fillTemplate(pin.template, vars);
  // Computed-only pins (not arguments of the operation) are available to guards but not sent.
  const accepted = operationArgNames(action.binding);
  const sendArgs = { ...opArgs };
  for (const [name] of pins) if (accepted.has(name)) sendArgs[name] = vars[name];
  return { sendArgs, vars };
}

/** The argument names an operation takes, per binding kind. */
function operationArgNames(binding) {
  const placeholders = (t) => [...String(t ?? "").matchAll(/\{(\w+)\}/g)].map((m) => m[1]);
  switch (binding.kind) {
    case "http":
      return new Set(binding.params.map((p) => p.name));
    case "cli":
      return new Set([...binding.options.map((o) => o.name), ...(binding.argv_template ?? []).flatMap(placeholders)]);
    case "electron":
      return new Set([...binding.params, ...(binding.rest ? [binding.rest] : [])]);
    case "adb":
      return new Set([...binding.binds.map((b) => b.name), ...binding.extras.map((e) => e.name), ...placeholders(binding.uri_template), ...placeholders(binding.data_uri_template)]);
    default:
      return new Set();
  }
}

async function checkGuards(action, vars) {
  for (const guard of action.guards ?? []) {
    const args = Object.fromEntries(Object.entries(guard.args ?? {}).map(([k, t]) => [k, fillTemplate(t, vars)]));
    const value = await callSupport(guard.operation, args, false);
    for (const [pointer, expected] of Object.entries(guard.require)) {
      const allowed = (Array.isArray(expected) ? expected : [expected]).map((e) => fillTemplate(e, vars));
      const actual = pointerGet(value, pointer);
      if (!allowed.some((a) => String(a) === String(actual))) {
        throw new Error(`Refused: ${guard.message ?? `${pointer} is ${JSON.stringify(actual)}, but only ${allowed.map((a) => JSON.stringify(a)).join(" or ")} is allowed.`}`);
      }
    }
  }
}

// `mcp-forge verify` sets this so drifted responses reach it whole; it then runs
// the same schema validation itself and reports which fields changed.
const rawOutputs = process.env.FORGE_VERIFY_RAW === "1";

function createServer() {
  const server = new McpServer({ name: manifest.server.name, version: manifest.server.version });
  for (const tool of manifest.tools) {
    if (tool.quarantined) continue;
    server.registerTool(
      tool.name,
      {
        title: tool.title,
        description: tool.description,
        inputSchema: fromJsonSchema(tool.input),
        ...(tool.output && !rawOutputs ? { outputSchema: fromJsonSchema(tool.output) } : {}),
        annotations: tool.annotations,
        _meta: tool.meta,
      },
      async (args) => {
        const routed = route(tool, args ?? {});
        if (routed.error) return fail(routed.error);
        try {
          const { sendArgs, vars } = await applyPins(routed.action, routed.opArgs);
          await checkGuards(routed.action, vars);
          return toolResult(routed.action, await runtimeFor(routed.action.binding.kind).invoke(routed.action, sendArgs));
        } catch (error) {
          return fail(String(error?.message ?? error));
        }
      },
    );
  }
  return server;
}

serveStdio(createServer, { onerror: (e) => console.error(e) });
